section Section1; shared RENAINF_infracoes_2026_com_competencia_pontos = let Origem = Excel.Workbook( Web.Contents("https://betinhos-my.sharepoint.com/personal/noreply_betinhos_onmicrosoft_com/Documents/Aplicativos/Microsoft Power Query/Uploaded Files/Tabela de Infrações e seus Valores 3.xlsx"), null, true ),
#"Navegação 1" = Origem{[Item = "RENAINF_infracoes_2026_com_competencia_pontos", Kind = "Table"]}[Data],
#"Tipo de coluna alterado" = Table.TransformColumnTypes( #"Navegação 1", { {"Código da Infração", Int64.Type}, {"Descrição da Infração", type text}, {"Amparo Legal", type text}, {"Infrator", type text}, {"Competência", type text}, {"Gravidade", type text}, {"Pontos", Int64.Type}, {"Valor", type number} } ),
// Pega apenas a PRIMEIRA opção antes da vírgula e converte para o VALUE do Choice (single select) #"Competencia_SingleValue" = Table.AddColumn( #"Tipo de coluna alterado", "Competencia_SingleValue", each let txt = [Competência], first = if txt = null or Text.Trim(txt) = "" then null else Text.Trim(Text.BeforeDelimiter(txt, ",")) in if first = "Municipal" then 202410000 else if first = "Rodoviário" then 202410001 else if first = "Estadual" then 202410002 else null, Int64.Type ),
// Remove a coluna de texto original #"Competência Removida" = Table.RemoveColumns( #"Competencia_SingleValue", {"Competência"} )
in #"Competência Removida";

section Section1; shared TabelaMultas = let // ========================= // FUNÇÕES (BLINDADAS) // ========================= fxNormalizeName = (v as nullable any) as nullable text => let t0 = if v = null then null else Text.Trim(Text.From(v)), t1 = if t0 = null or t0 = "" then null else Text.Upper(t0),
// normaliza espaços t2 = if t1 = null then null else Text.Combine( List.Select( Text.SplitAny(t1, " " & Character.FromNumber(9) & Character.FromNumber(10) & Character.FromNumber(13)), each _ <> "" ), " " ),
// remove acentos (suficiente PT-BR) replFrom = { "Á","À","Â","Ã","Ä","Å","Æ","Ç","É","È","Ê","Ë","Í","Ì","Î","Ï","Ñ","Ó","Ò","Ô","Õ","Ö","Ø","Ú","Ù","Û","Ü","Ý", "á","à","â","ã","ä","å","æ","ç","é","è","ê","ë","í","ì","î","ï","ñ","ó","ò","ô","õ","ö","ø","ú","ù","û","ü","ý" }, replTo = { "A","A","A","A","A","A","AE","C","E","E","E","E","I","I","I","I","N","O","O","O","O","O","O","U","U","U","U","Y", "A","A","A","A","A","A","AE","C","E","E","E","E","I","I","I","I","N","O","O","O","O","O","O","U","U","U","U","Y" },
t3 = if t2 = null then null else List.Accumulate( List.Positions(replFrom), t2, (state, i) => Text.Replace(state, replFrom{i}, replTo{i}) ),
// remove aspas e símbolos comuns t4 = if t3 = null then null else List.Accumulate( {"'","""","’","`","´","“","”"}, t3, (state, ch) => Text.Replace(state, ch, "") ),
// mantém letras/números/espaço allowed = {"A".."Z","0".."9"," "}, t5 = if t4 = null then null else Text.Trim(Text.Combine(List.Select(Text.ToList(t4), each List.Contains(allowed, _)), "")),
// colapsa espaços de novo t6 = if t5 = null then null else Text.Combine( List.Select(Text.Split(t5, " "), each _ <> ""), " " ) in t6,
// procura mapeamento numa tabelinha (sem Record => evita "Invalid identifier") fxMap = (key as nullable text, mapTable as table) as nullable text => let hit = if key = null then null else try Table.SelectRows(mapTable, each [Key] = key) otherwise null, out = if hit = null or Table.RowCount(hit) = 0 then null else hit{0}[Value] in out,
// ========================= // ORIGEM // ========================= Origem = Excel.Workbook( Web.Contents( "https://betinhos-my.sharepoint.com/personal/betinhos_betinhos_onmicrosoft_com/Documents/Documentos%20de%20Betinhos%20Executive%20Service/Frotas/Gest%C3%A3o%20de%20multas%20atualizada_2025.xlsx" ), null, true ),
#"Navegação 1" = Origem{[Item = "TabelaMultas", Kind = "Table"]}[Data],
#"Tipo de coluna alterado" = Table.TransformColumnTypes( #"Navegação 1", { {"Status", type text}, {"NUMERO DE REGISTRO", Int64.Type}, {"Data", type date}, {"Placa", type text}, {"Local da infração", type text}, {"Cidade", type text}, {"Motorista", type text}, {"Indicado", type text}, {"Comentários", type text}, {"Nome da multa", type text}, {"Valor", type number}, {"Pontos", Int64.Type}, {"Gravidade", type text} } ),
#"Texto em maiúscula" = Table.TransformColumns( #"Tipo de coluna alterado", {{"Placa", each if _ = null then null else Text.Upper(Text.Trim(_)), type nullable text}} ),
#"Tipo de coluna alterado 1" = if Table.HasColumns(#"Texto em maiúscula", {"Hrs"}) then Table.TransformColumnTypes(#"Texto em maiúscula", {{"Hrs", type time}}) else #"Texto em maiúscula",
#"Todas as palavras foram colocadas em maiúscula" = Table.TransformColumns( #"Tipo de coluna alterado 1", {{"Status", each if _ = null then null else Text.Proper(Text.Trim(_)), type nullable text}} ),
#"Valor substituído" = Table.ReplaceValue(#"Todas as palavras foram colocadas em maiúscula", "Paga", "Pago", Replacer.ReplaceText, {"Status"}),
#"Valor substituído 1" = Table.ReplaceValue(#"Valor substituído", "Comunicado", "Condutor Notificado", Replacer.ReplaceText, {"Status"}),
#"Valor substituído 2" = Table.ReplaceValue(#"Valor substituído 1", "A Descontar", "Descontado", Replacer.ReplaceText, {"Status"}),
#"Valor substituído 3" = Table.ReplaceValue(#"Valor substituído 2", "Notificar O Condutor", "Notificar o Condutor", Replacer.ReplaceText, {"Status"}),
#"Colunas renomeadas" = if Table.HasColumns(#"Valor substituído 3", {"Hrs"}) then Table.RenameColumns(#"Valor substituído 3", {{"Hrs", "Hora"}}) else #"Valor substituído 3",
// Data + Hora => DataHora #"DataHora adicionada" = Table.AddColumn( #"Colunas renomeadas", "DataHora", each try #datetime( Date.Year([Data]), Date.Month([Data]), Date.Day([Data]), if Record.HasFields(_, "Hora") and [Hora] <> null then Time.Hour([Hora]) else 0, if Record.HasFields(_, "Hora") and [Hora] <> null then Time.Minute([Hora]) else 0, if Record.HasFields(_, "Hora") and [Hora] <> null then Time.Second([Hora]) else 0 ) otherwise null, type datetime ),
#"Colunas renomeadas 1" = if Table.HasColumns(#"DataHora adicionada", {"Numero Notifcação"}) then Table.RenameColumns(#"DataHora adicionada", {{"Numero Notifcação", "Numero Notificação"}}) else #"DataHora adicionada",
// Numero Notificação => só A-Z/0-9 #"NumeroNotificacao limpo" = if Table.HasColumns(#"Colunas renomeadas 1", {"Numero Notificação"}) then Table.TransformColumns( #"Colunas renomeadas 1", { { "Numero Notificação", each if _ = null then null else Text.Upper(Text.Select(Text.From(_), {"A".."Z","0".."9"})), type nullable text } } ) else #"Colunas renomeadas 1",
// Código da infração => só números (4 primeiros) #"CodigoInfracao normalizado" = if Table.HasColumns(#"NumeroNotificacao limpo", {"Código da infração"}) then Table.TransformColumns( #"NumeroNotificacao limpo", { { "Código da infração", each if _ = null then null else Text.Start(Text.Select(Text.From(_), {"0".."9"}), 4), type nullable text } } ) else #"NumeroNotificacao limpo",
#"Tipo de coluna alterado 2" = if Table.HasColumns(#"CodigoInfracao normalizado", {"Valor"}) then Table.TransformColumnTypes(#"CodigoInfracao normalizado", {{"Valor", Currency.Type}}) else #"CodigoInfracao normalizado",
// Indicado => logical #"Indicado (logical) corrigido" = if Table.HasColumns(#"Tipo de coluna alterado 2", {"Indicado"}) then Table.TransformColumns( #"Tipo de coluna alterado 2", { { "Indicado", each let t = if _ = null then "" else Text.Lower(Text.Trim(Text.From(_))) in if t = "" then true else if t = "sim" or t = "s" or t = "true" or t = "verdadeiro" or t = "1" then true else if t = "não" or t = "nao" or t = "n" or t = "false" or t = "falso" or t = "0" then false else null, type nullable logical } } ) else #"Tipo de coluna alterado 2",
// ========================= // MOTORISTA (MESCLAR: criar se não existir) // ========================= #"Motorista Original" = if Table.HasColumns(#"Indicado (logical) corrigido", {"Motorista"}) then Table.AddColumn(#"Indicado (logical) corrigido", "Motorista_Original", each [Motorista], type nullable text) else #"Indicado (logical) corrigido",
// lista dos "selecionados" (prints) -> normalizados allowedSelected = List.RemoveNulls( List.Transform( { "(null)", "Betinho", "Carlos Alves", "Danilo Novaes", "Delio Ruben", "Eduardo Calastri", "Eduardo Oliveira", "Empresa", "Escritorio", "Escritório", "Gerson Luiz", "Gilmar Augusto Dos Santos", "Ibrahim Khalil", "Isael Neto", "Josmar Alberto Correa", "José Amadeu", "Locacao", "Locação", "Marcos Vinicius Menecucci", "Marcuis Wagner", "Marcus Wagner", "Mauricio Amaral", "Normando Cunha", "Ricardo Schenkel", "Robson Santos", "Sebastião Diniz", "Washington Santos" }, each fxNormalizeName(_) ) ),
// tabela DE/PARA (Key normalizada -> Value final) mapTable = #table( type table [Key = text, Value = text], { {"BETINHO", "Betinho"}, {"CARLOS ALVES", "Carlos Alberto Alves dos Santos"}, {"DANILO NOVAES", "Danilo Novaes de Oliveira"}, {"EDUARDO CALASTRI", "Eduardo Rocha Calastri"}, {"GILMAR AUGUSTO DOS SANTOS", "Gilmar Augusto Gonçalves"}, {"IBRAHIM KHALIL", "Ibrahim Khalil Chahine Neto"}, {"ISAEL NETO", "Isael Alves Neto"}, {"JOSMAR ALBERTO CORREA", "Josmar Alberto Correa"}, {"JOSE AMADEU", "José Amadeu Nunes"}, {"LOCACAO", "Locatário do veículo da Betinhos"}, {"MAURICIO AMARAL", "Mauricio Amaral"}, {"NORMANDO CUNHA", "Normando Cunha"}, {"ROBSON SANTOS", "Robson dos Santos"}, {"SEBASTIAO DINIZ", "Sebastião Reginaldo Diniz"}, {"WASHINGTON SANTOS", "Washington Santos"},
// regra: escritório => empresa {"ESCRITORIO", "Empresa"}, {"EMPRESA", "Empresa"},
// Marcus/Marcuis => mesma pessoa {"MARCUS WAGNER", "Marcus Wagner"}, {"MARCUIS WAGNER", "Marcus Wagner"} } ),
#"Motorista preparado p/ Dataverse" = if Table.HasColumns(#"Motorista Original", {"Motorista"}) then Table.TransformColumns( #"Motorista Original", { { "Motorista", each let original = if _ = null then null else Text.Trim(Text.From(_)), norm = fxNormalizeName(original), mapped = fxMap(norm, mapTable) in // ignora não selecionado if norm = null then null else if not List.Contains(allowedSelected, norm) then null // (null) textual => null else if norm = "(NULL)" then null // usa DE/PARA quando existir else if mapped <> null then mapped // senão mantém valor original (pra ser CRIADO no Dataverse no mesclar) else original, type nullable text } } ) else #"Motorista Original",
// mantém seu filtro antigo + remove Motorista = null #"Linhas filtradas" = Table.SelectRows( #"Motorista preparado p/ Dataverse", each ([Motorista] <> null) and ([Motorista_Original] <> "Bruno Vieira" and [Motorista_Original] <> "Emerson" and [Motorista_Original] <> "Geovaneo Coutinho" and [Motorista_Original] <> "Jorge Ramirez" and [Motorista_Original] <> "Mauro") ),
// opcional: remover auditoria #"Remover coluna auditoria" = if Table.HasColumns(#"Linhas filtradas", {"Motorista_Original"}) then Table.RemoveColumns(#"Linhas filtradas", {"Motorista_Original"}) else #"Linhas filtradas"
in #"Remover coluna auditoria";

section Section1; shared Tabela1 = let Origem = Excel.Workbook( Web.Contents( "https://betinhos-my.sharepoint.com/personal/betinhos_betinhos_onmicrosoft_com/Documents/Documentos%20de%20Betinhos%20Executive%20Service/Frotas/Frota.xlsx" ), null, true ),
#"Navegação 1" = Origem{[Item = "Tabela1", Kind = "Table"]}[Data],
// Tipos: mantenho como texto tudo que costuma vir "sujo" #"Tipo de coluna alterado" = Table.TransformColumnTypes( #"Navegação 1", { {"ID", Int64.Type}, {"Start time", type datetime}, {"Completion time", type datetime}, {"Email", type text}, {"Name", type text}, {"Veículo", type text}, {"Gravidade", type text}, {"Descreva a manutenção necessária", type text}, {"Fotos", type text}, {"Ação adotada", type text}, {"Km atual", type text} } ),
// =========================== // GRAVIDADE (substituições seguras) // =========================== #"Gravidade normalizada" = Table.TransformColumns( #"Tipo de coluna alterado", { { "Gravidade", each let t = Text.Trim(try Text.From(_) otherwise "") in if t = "" then null else if Text.Upper(t) = "REALIZADO" then "Média" else t, type text } } ),
// =========================== // PLACA (blindado: AAA0000 ou AAA0A00; aceita "RFV 4E20") // =========================== #"Placa adicionada" = Table.AddColumn( #"Gravidade normalizada", "Placa", each let veiculo = [Veículo], raw0 = try Text.From(veiculo) otherwise "", raw1 = Text.Trim(raw0), upper = Text.Upper(raw1),
allowed = List.Combine({{"A".."Z"}, {"0".."9"}, {" "}, {"-"}}), cleaned = Text.Combine(List.Select(Text.ToList(upper), each List.Contains(allowed, _))),
tokens0 = List.Select(Text.SplitAny(cleaned, " -"), each _ <> ""), tokens1 = List.Transform(tokens0, each Text.Trim(_)), tokens = List.Select(tokens1, each _ <> ""),
idx = {0 .. List.Max({-1, List.Count(tokens) - 2})}, pairs = List.Transform(idx, each tokens{_} & tokens{_ + 1}),
candidates = List.Distinct( List.Transform(tokens, each Text.Replace(_, " ", "")) & pairs ),
IsPlate = (t as text) as logical => let s = Text.Replace(Text.Trim(t), " ", ""), len = Text.Length(s), okLen = len = 7,
c1 = if okLen then Text.At(s, 0) else "", c2 = if okLen then Text.At(s, 1) else "", c3 = if okLen then Text.At(s, 2) else "", c4 = if okLen then Text.At(s, 3) else "", c5 = if okLen then Text.At(s, 4) else "", c6 = if okLen then Text.At(s, 5) else "", c7 = if okLen then Text.At(s, 6) else "",
isLetter = (c as text) as logical => List.Contains({"A".."Z"}, c), isDigit = (c as text) as logical => List.Contains({"0".."9"}, c),
old = okLen and isLetter(c1) and isLetter(c2) and isLetter(c3) and isDigit(c4) and isDigit(c5) and isDigit(c6) and isDigit(c7),
mercosul = okLen and isLetter(c1) and isLetter(c2) and isLetter(c3) and isDigit(c4) and isLetter(c5) and isDigit(c6) and isDigit(c7) in old or mercosul,
found = List.Select(candidates, each IsPlate(_)), result = if List.Count(found) > 0 then found{0} else null in result, type text ),
// =========================== // KM ATUAL -> somente números (blindado contra null, "Km", ".", espaços) // =========================== #"Km_Atual_Num adicionada" = Table.AddColumn( #"Placa adicionada", "KM_Atual_Num", each let kmRaw = [#"Km atual"],
// blindagem total contra null / erro kmText = if kmRaw = null then "" else try Text.From(kmRaw) otherwise "",
kmTrim = Text.Trim(kmText),
// mantém somente dígitos digitsOnly = Text.Combine( List.Select( Text.ToList(kmTrim), each List.Contains({"0".."9"}, _) ) ),
result = if digitsOnly = "" then null else try Number.FromText(digitsOnly) otherwise null in result, Int64.Type ) ,
// =========================== // FOTOS -> Foto 01/02/03 (até 3 links, funciona com 0/1/2/3) // =========================== #"Fotos split adicionada" = Table.AddColumn( #"Km_Atual_Num adicionada", "Fotos_List", each let f0 = try Text.From([Fotos]) otherwise "", f1 = Text.Trim(f0),
// separa por ; e remove vazios; trim em cada item parts0 = if f1 = "" then {} else Text.Split(f1, ";"), parts1 = List.Transform(parts0, each Text.Trim(_)), parts = List.Select(parts1, each _ <> "") in parts, type list ),
#"Foto 01" = Table.AddColumn( #"Fotos split adicionada", "Foto 01", each try [Fotos_List]{0} otherwise null, type text ),
#"Foto 02" = Table.AddColumn( #"Foto 01", "Foto 02", each try [Fotos_List]{1} otherwise null, type text ),
#"Foto 03" = Table.AddColumn( #"Foto 02", "Foto 03", each try [Fotos_List]{2} otherwise null, type text ),
#"Remove coluna auxiliar Fotos_List" = Table.RemoveColumns(#"Foto 03", {"Fotos_List"}), #"Personalização adicionada" = Table.TransformColumnTypes(Table.AddColumn(#"Remove coluna auxiliar Fotos_List", "Email_norm", each Text.Lower(Text.Trim([Email]))), {{"Email_norm", type text}}), #"Consultas mescladas" = Table.NestedJoin(#"Personalização adicionada", {"Email_norm"}, cr40f_funcionarios, {"Email_norm"}, "cr40f_funcionarios", JoinKind.LeftOuter), #"Expandido cr40f_funcionarios" = Table.ExpandTableColumn(#"Consultas mescladas", "cr40f_funcionarios", {"cr40f_funcionariosid", "cr40f_nomecompleto"}, {"cr40f_funcionariosid", "cr40f_nomecompleto"}), #"Personalização adicionada 1" = Table.TransformColumnTypes(Table.AddColumn(#"Expandido cr40f_funcionarios", "Status Realizado", each "Realizado"), {{"Status Realizado", type text}}), #"Linhas filtradas" = Table.SelectRows(#"Personalização adicionada 1", each not Text.Contains([Descreva a manutenção necessária], "teste") and not Text.Contains([Descreva a manutenção necessária], "Teste")) in #"Linhas filtradas"; shared cr40f_funcionarios = let Origem = CommonDataService.Database("org23b93544.crm2.dynamics.com", [CreateNavigationProperties = null]), #"Navegação 1" = Origem{[Schema = "dbo", Item = "cr40f_funcionarios"]}[Data], #"Personalização adicionada" = Table.TransformColumnTypes(Table.AddColumn(#"Navegação 1", "Email_norm", each Text.Lower(Text.Trim([cr40f_emailmicrosoft]))), {{"Email_norm", type text}}) in #"Personalização adicionada";
